import {
    useId, useLayoutEffect, useRef, useState,
    type ComponentProps, type DragEvent, type ReactNode,
} from "react";
import { cn } from "./utils";

type KanbanCard = {
    id: string;
    title: string;
    description?: string;
    swimlaneId?: string;
};

type KanbanSwimlane = {
    id: string;
    title: string;
};

type KanbanColumn<Card extends KanbanCard = KanbanCard> = {
    id: string;
    title: string;
    cards: readonly Card[];
    wipLimit?: number;
};

type KanbanMove = {
    cardId: string;
    fromColumnId: string;
    toColumnId: string;
    fromIndex: number;
    toIndex: number;
};

type KanbanProps<Card extends KanbanCard = KanbanCard> = Omit<
    ComponentProps<"div">, "children"
> & {
    label: string;
    columns: readonly KanbanColumn<Card>[];
    onColumnsChange: (
        columns: KanbanColumn<Card>[], move: KanbanMove,
    ) => void | Promise<void>;
    renderCard?: (card: Card) => ReactNode;
    swimlanes?: readonly KanbanSwimlane[];
    wipPolicy?: "warn" | "block";
    canMove?: (card: Card, move: KanbanMove) => boolean;
    collapsibleColumns?: boolean;
};

const actionLabels = {
    left: "왼쪽 열로",
    right: "오른쪽 열로",
    up: "위로",
    down: "아래로",
} as const;

const unassignedLaneId = "__kanban_unassigned__";

function validateColumns<Card extends KanbanCard>(
    columns: readonly KanbanColumn<Card>[],
) {
    if (columns.length === 0) {
        throw new Error("Kanban requires at least one column.");
    }
    const columnIds = new Set<string>();
    const cardIds = new Set<string>();

    for (const column of columns) {
        if (!column.id.trim() || !column.title.trim() ||
            columnIds.has(column.id)) {
            throw new Error("Kanban columns need unique IDs and titles.");
        }
        if (column.wipLimit !== undefined &&
            (!Number.isInteger(column.wipLimit) || column.wipLimit < 0)) {
            throw new RangeError("Kanban WIP limits must be nonnegative integers.");
        }
        columnIds.add(column.id);
        for (const card of column.cards) {
            if (!card.id.trim() || !card.title.trim() ||
                cardIds.has(card.id)) {
                throw new Error("Kanban cards need unique IDs and titles.");
            }
            if (card.swimlaneId !== undefined && !card.swimlaneId.trim()) {
                throw new Error("Kanban swimlane IDs cannot be empty.");
            }
            cardIds.add(card.id);
        }
    }
}

function moveKanbanCard<Card extends KanbanCard>(
    columns: readonly KanbanColumn<Card>[],
    cardId: string,
    toColumnId: string,
    beforeCardId: string | null = null,
): { columns: KanbanColumn<Card>[]; move: KanbanMove } | null {
    validateColumns(columns);
    const fromColumn = columns.find((column) =>
        column.cards.some((card) => card.id === cardId));
    const targetColumn = columns.find((column) =>
        column.id === toColumnId);
    if (!fromColumn) throw new RangeError("Kanban card was not found.");
    if (!targetColumn) throw new RangeError("Kanban column was not found.");
    if (beforeCardId === cardId) return null;

    const fromIndex = fromColumn.cards.findIndex((card) =>
        card.id === cardId);
    const next = columns.map((column) => ({
        ...column,
        cards: [...column.cards],
    }));
    const source = next.find((column) => column.id === fromColumn.id)!;
    const target = next.find((column) => column.id === toColumnId)!;
    const [card] = source.cards.splice(fromIndex, 1);
    const toIndex = beforeCardId === null
        ? target.cards.length
        : target.cards.findIndex((item) => item.id === beforeCardId);
    if (toIndex < 0) {
        throw new RangeError("Kanban target card was not found in its column.");
    }
    if (source === target && toIndex === fromIndex) return null;
    target.cards.splice(toIndex, 0, card);

    return {
        columns: next,
        move: {
            cardId,
            fromColumnId: fromColumn.id,
            toColumnId,
            fromIndex,
            toIndex,
        },
    };
}

type LaneEntry = {
    id: string | null;
    title: string | null;
};

type FailedMove = {
    cardId: string;
    fromColumnId: string;
    fromIndex: number;
    sourceSwimlaneId: string | undefined;
    toColumnId: string;
    beforeCardId: string | null;
};

function errorMessage(reason: unknown) {
    return reason instanceof Error && reason.message.trim()
        ? reason.message : "카드 이동을 저장하지 못했습니다. 다시 시도하세요.";
}

function Kanban<Card extends KanbanCard = KanbanCard>({
    label,
    columns,
    onColumnsChange,
    renderCard,
    swimlanes,
    wipPolicy = "warn",
    canMove,
    collapsibleColumns = false,
    className,
    ...props
}: KanbanProps<Card>) {
    if (!label.trim()) throw new Error("Kanban needs a board label.");
    if (wipPolicy !== "warn" && wipPolicy !== "block") {
        throw new RangeError("Kanban WIP policy must be warn or block.");
    }
    validateColumns(columns);
    const laneIds = new Set<string>();
    for (const lane of swimlanes ?? []) {
        if (!lane.id.trim() || !lane.title.trim() || laneIds.has(lane.id) ||
            lane.id === unassignedLaneId) {
            throw new Error("Kanban swimlanes need unique IDs and titles.");
        }
        laneIds.add(lane.id);
    }
    if (swimlanes) {
        for (const card of columns.flatMap((column) => column.cards)) {
            if (card.swimlaneId && !laneIds.has(card.swimlaneId)) {
                throw new Error(`Unknown Kanban swimlane: ${card.swimlaneId}`);
            }
        }
    }

    const id = useId();
    const boardRef = useRef<HTMLDivElement>(null);
    const draggedCard = useRef<string | null>(null);
    const pendingFocus = useRef<string | null>(null);
    const retryRef = useRef<HTMLButtonElement>(null);
    const [dragging, setDragging] = useState<string | null>(null);
    const [announcement, setAnnouncement] = useState("");
    const [message, setMessage] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [saving, setSaving] = useState(false);
    const [failedMove, setFailedMove] = useState<FailedMove | null>(
        null,
    );
    const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(
        () => new Set(),
    );
    const lanes: LaneEntry[] = swimlanes
        ? [
            ...swimlanes.map((lane) => ({ id: lane.id, title: lane.title })),
            ...(columns.some((column) => column.cards.some((card) =>
                !card.swimlaneId,
            )) ? [{ id: unassignedLaneId, title: "분류 없음" }] : []),
        ]
        : [{ id: null, title: null }];

    useLayoutEffect(() => {
        if (failedMove) {
            retryRef.current?.focus();
            return;
        }
        if (!pendingFocus.current) return;
        const card = [...(boardRef.current?.querySelectorAll<HTMLElement>(
            "[data-kanban-card]",
        ) ?? [])].find((item) =>
            item.dataset.kanbanCard === pendingFocus.current);
        const action = card?.querySelector<HTMLButtonElement>(
            "button[data-kanban-action]:not([aria-disabled='true'])",
        );
        (action ?? card)?.focus();
        pendingFocus.current = null;
    }, [columns, failedMove, saving]);

    function findCard(cardId: string) {
        return columns.flatMap((column) => column.cards)
            .find((card) => card.id === cardId);
    }

    function getRestriction(
        card: Card,
        move: KanbanMove,
    ) {
        const target = columns.find((column) =>
            column.id === move.toColumnId)!;
        if (wipPolicy === "block" && move.fromColumnId !== move.toColumnId &&
            target.wipLimit !== undefined &&
            target.cards.length >= target.wipLimit) {
            return `${target.title} 열의 WIP 한도 ` +
                `${target.wipLimit}개에 도달해 이동할 수 없습니다.`;
        }
        if (canMove && !canMove(card, move)) {
            return `${target.title} 열로 허용되지 않은 상태 전환입니다.`;
        }
        return null;
    }

    function canRequestMove(
        card: Card,
        toColumn: KanbanColumn<Card>,
        beforeCardId: string | null,
    ) {
        const proposal = moveKanbanCard(
            columns, card.id, toColumn.id, beforeCardId,
        );
        return Boolean(proposal && !getRestriction(card, proposal.move));
    }

    async function persistMove(
        proposal: { columns: KanbanColumn<Card>[]; move: KanbanMove },
        card: Card,
        restoreFocus: boolean,
        intent: FailedMove,
        retrying = false,
    ) {
        if (saving || (failedMove && !retrying)) return;
        pendingFocus.current = restoreFocus ? card.id : null;
        setSaving(true);
        setError(null);
        setMessage(null);
        try {
            await onColumnsChange(proposal.columns, proposal.move);
            setFailedMove(null);
            setAnnouncement(`${card.title}: ${proposal.move.toColumnId} 열의 ` +
                `${proposal.move.toIndex + 1}번째 위치로 이동했습니다.`);
        } catch (reason) {
            pendingFocus.current = null;
            setFailedMove(intent);
            setError(errorMessage(reason));
        } finally {
            setSaving(false);
        }
    }

    function move(
        card: Card,
        toColumn: KanbanColumn<Card>,
        beforeCardId: string | null = null,
        restoreFocus = false,
    ) {
        if (saving || failedMove) return;
        const proposal = moveKanbanCard(
            columns, card.id, toColumn.id, beforeCardId,
        );
        if (!proposal) return;
        const restriction = getRestriction(card, proposal.move);
        if (restriction) {
            setMessage(restriction);
            setAnnouncement(restriction);
            return;
        }
        void persistMove(proposal, card, restoreFocus, {
            cardId: card.id,
            fromColumnId: proposal.move.fromColumnId,
            fromIndex: proposal.move.fromIndex,
            sourceSwimlaneId: card.swimlaneId,
            toColumnId: proposal.move.toColumnId,
            beforeCardId,
        });
    }

    function cancelFailedMove(reason: string, cardId?: string) {
        pendingFocus.current = cardId ?? null;
        setFailedMove(null);
        setError(reason);
        setMessage(reason);
        setAnnouncement(reason);
    }

    async function retryMove() {
        if (!failedMove || saving) return;
        const card = findCard(failedMove.cardId);
        if (!card) {
            cancelFailedMove("이동할 카드가 현재 보드에 없어 재시도를 취소했습니다.");
            return;
        }
        const source = columns.find((column) =>
            column.cards.some((item) => item.id === failedMove.cardId),
        );
        const sourceIndex = source?.cards.findIndex((item) =>
            item.id === failedMove.cardId,
        ) ?? -1;
        if (source?.id !== failedMove.fromColumnId ||
            sourceIndex !== failedMove.fromIndex ||
            card.swimlaneId !== failedMove.sourceSwimlaneId) {
            cancelFailedMove(
                "원본 카드 위치가 바뀌어 재시도를 취소했습니다. 다시 이동해 주세요.",
                card.id,
            );
            return;
        }
        const target = columns.find((column) =>
            column.id === failedMove.toColumnId,
        );
        if (!target || (failedMove.beforeCardId !== null &&
            !target.cards.some((item) => item.id === failedMove.beforeCardId))) {
            cancelFailedMove(
                "이동 대상이 바뀌어 재시도를 취소했습니다. 다시 이동해 주세요.",
                card.id,
            );
            return;
        }
        const proposal = moveKanbanCard(
            columns, card.id, target.id, failedMove.beforeCardId,
        );
        if (!proposal) {
            cancelFailedMove(
                "이동 위치가 바뀌어 재시도를 취소했습니다. 다시 이동해 주세요.",
                card.id,
            );
            return;
        }
        const restriction = getRestriction(card, proposal.move);
        if (restriction) {
            cancelFailedMove(
                `${restriction} 재시도를 취소했습니다. 다시 이동해 주세요.`,
                card.id,
            );
            return;
        }
        await persistMove(proposal, card, true, failedMove, true);
    }

    function beginDrag(event: DragEvent, cardId: string) {
        if (saving || failedMove) {
            event.preventDefault();
            return;
        }
        draggedCard.current = cardId;
        setDragging(cardId);
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", cardId);
    }

    function endDrag() {
        draggedCard.current = null;
        setDragging(null);
    }

    function allowDrop(event: DragEvent) {
        if (!draggedCard.current || saving || failedMove) return;
        event.preventDefault();
        event.dataTransfer.dropEffect = "move";
    }

    function dropOnColumn(
        event: DragEvent,
        column: KanbanColumn<Card>,
        lane: LaneEntry,
    ) {
        event.preventDefault();
        const card = draggedCard.current
            ? findCard(draggedCard.current) : undefined;
        const destinationLaneId = lane.id === unassignedLaneId
            ? undefined : lane.id;
        if (card && swimlanes &&
            card.swimlaneId !== destinationLaneId) {
            const explanation = "카드는 다른 swimlane으로 이동할 수 없습니다.";
            setMessage(explanation);
            setAnnouncement(explanation);
        } else if (card) {
            move(card, column);
        }
        endDrag();
    }

    function dropBeforeCard(
        event: DragEvent, column: KanbanColumn<Card>, before: Card,
    ) {
        event.preventDefault();
        event.stopPropagation();
        const card = draggedCard.current
            ? findCard(draggedCard.current) : undefined;
        if (card && card.swimlaneId === before.swimlaneId) {
            move(card, column, before.id);
        } else if (card) {
            const explanation = "카드는 다른 swimlane으로 이동할 수 없습니다.";
            setMessage(explanation);
            setAnnouncement(explanation);
        }
        endDrag();
    }

    function laneCards(column: KanbanColumn<Card>, lane: LaneEntry) {
        if (lane.id === null) return column.cards;
        if (lane.id === unassignedLaneId) {
            return column.cards.filter((card) => !card.swimlaneId);
        }
        return column.cards.filter((card) => card.swimlaneId === lane.id);
    }

    function toggleColumn(columnId: string) {
        setCollapsed((current) => {
            const next = new Set(current);
            if (next.has(columnId)) next.delete(columnId);
            else next.add(columnId);
            return next;
        });
    }

    function renderColumn(column: KanbanColumn<Card>, columnIndex: number,
        lane: LaneEntry, laneIndex: number) {
        const cards = laneCards(column, lane);
        const isCollapsed = collapsed.has(column.id);
        const overLimit = column.wipLimit !== undefined &&
            column.cards.length > column.wipLimit;
        const laneLabel = lane.title ? ` (${lane.title})` : "";
        return (
            <section
                key={column.id}
                data-ui="kanban-column"
                data-surface="panel"
                data-wip-exceeded={overLimit || undefined}
                aria-labelledby={`${id}-column-${laneIndex}-${columnIndex}`}
                className={cn(
                    "w-64 shrink-0 rounded-sm border border-border " +
                    "bg-surface-subtle p-[var(--space-3)]",
                    dragging && "border-dashed",
                )}
                onDragOver={allowDrop}
                onDrop={(event) => dropOnColumn(event, column, lane)}
            >
                <h3 id={`${id}-column-${laneIndex}-${columnIndex}`}
                    data-slot="surface-header"
                    className={
                        "mb-[var(--space-3)] flex items-center " +
                        "justify-between gap-2 text-sm font-semibold"
                    }>
                    <span data-slot="surface-title">{column.title}</span>
                    <span className="flex items-center gap-2">
                        <span data-slot="surface-meta"
                            className="text-xs font-normal text-muted">
                            {column.cards.length}
                            {column.wipLimit !== undefined &&
                                ` / ${column.wipLimit}`}
                        </span>
                        {collapsibleColumns && (
                            <button type="button"
                                aria-label={`${column.title} 열 ` +
                                    `${isCollapsed ? "펼치기" : "접기"}${laneLabel}`}
                                aria-expanded={!isCollapsed}
                                onClick={() => toggleColumn(column.id)}
                                className={"rounded-sm px-1 py-0.5 text-xs " +
                                    "focus-visible:outline-2 " +
                                    "focus-visible:outline-focus"}>
                                {isCollapsed ? "펼치기" : "접기"}
                            </button>
                        )}
                    </span>
                </h3>
                {overLimit && laneIndex === 0 && (
                    <p role="status" data-slot="kanban-wip-warning"
                        className={"mb-2 rounded-sm border border-warning/40 " +
                            "bg-warning/10 p-2 text-xs text-foreground"}>
                        {column.title} 열의 WIP 한도 {column.wipLimit}개를
                        초과했습니다.
                    </p>
                )}
                {!isCollapsed && (cards.length === 0 ? (
                    <p className={
                        "rounded-sm border border-dashed " +
                        "border-border p-[var(--space-3)] text-xs text-muted"
                    } data-surface="drop-target">
                        카드가 없습니다
                    </p>
                ) : (
                    <ul className="grid gap-[var(--space-2)]">
                        {cards.map((card, cardIndex) => {
                            const previous = cards[cardIndex - 1];
                            const afterNext = cards[cardIndex + 2];
                            const targets = [
                                columnIndex > 0
                                    ? columns[columnIndex - 1] : null,
                                columnIndex < columns.length - 1
                                    ? columns[columnIndex + 1] : null,
                                column,
                                column,
                            ];
                            const beforeIds = [null, null,
                                previous?.id ?? null, afterNext?.id ?? null];
                            const enabled = [columnIndex > 0,
                                columnIndex < columns.length - 1,
                                cardIndex > 0, cardIndex < cards.length - 1];
                            return (
                                <li
                                    key={card.id}
                                    data-kanban-card={card.id}
                                    data-surface="row"
                                    tabIndex={-1}
                                    draggable={!saving && !failedMove}
                                    onDragStart={(event) =>
                                        beginDrag(event, card.id)}
                                    onDragEnd={endDrag}
                                    onDragOver={allowDrop}
                                    onDrop={(event) =>
                                        dropBeforeCard(event, column, card)}
                                    className={cn(
                                        "rounded-sm border border-border " +
                                        "bg-surface p-[var(--space-3)] " +
                                        "shadow-[var(--shadow-float)]",
                                        dragging === card.id && "opacity-50",
                                    )}
                                >
                                    {renderCard ? renderCard(card) : (
                                        <>
                                            <p className="m-0 text-sm font-medium">
                                                {card.title}
                                            </p>
                                            {card.description && (
                                                <p className="mb-0 mt-1 text-xs text-muted">
                                                    {card.description}
                                                </p>
                                            )}
                                        </>
                                    )}
                                    <div role="group"
                                        aria-label={`${card.title} 이동`}
                                        className="mt-[var(--space-2)] flex gap-1">
                                        {(["left", "right", "up", "down"] as
                                            const).map((direction, index) => {
                                            const target = targets[index];
                                            const beforeId = beforeIds[index];
                                            const allowed = enabled[index] &&
                                                target !== null &&
                                                canRequestMove(card, target,
                                                    beforeId);
                                            const policyDenied = enabled[index] &&
                                                target !== null && !allowed;
                                            return (
                                                <button
                                                    key={direction}
                                                    type="button"
                                                    data-kanban-action={direction}
                                                    data-slot="surface-action"
                                                    aria-label={
                                                        `${card.title} ${actionLabels[direction]} 이동`
                                                    }
                                                    aria-disabled={!allowed ||
                                                        saving ||
                                                        failedMove !== null}
                                                    disabled={!enabled[index] ||
                                                        saving ||
                                                        failedMove !== null}
                                                    title={policyDenied
                                                        ? "허용되지 않은 이동" : undefined}
                                                    className={
                                                        "grid size-7 place-items-center rounded-sm " +
                                                        "border border-border text-xs " +
                                                        "hover:bg-surface-subtle disabled:opacity-40"
                                                    }
                                                    onClick={() => {
                                                        if (!target) return;
                                                        if (!allowed) {
                                                            const result =
                                                                moveKanbanCard(
                                                                    columns,
                                                                    card.id,
                                                                    target.id,
                                                                    beforeId,
                                                                );
                                                            if (result) {
                                                                const reason =
                                                                    getRestriction(
                                                                        card,
                                                                        result.move,
                                                                    );
                                                                if (reason) {
                                                                    setMessage(reason);
                                                                    setAnnouncement(reason);
                                                                }
                                                            }
                                                            return;
                                                        }
                                                        move(card, target,
                                                            beforeId, true);
                                                    }}
                                                >
                                                    <span aria-hidden="true">
                                                        {direction === "left" ? "←" :
                                                            direction === "right" ? "→" :
                                                                direction === "up" ? "↑" : "↓"}
                                                    </span>
                                                </button>
                                            );
                                        })}
                                    </div>
                                </li>
                            );
                        })}
                    </ul>
                ))}
                {isCollapsed && (
                    <p className="m-0 text-xs text-muted">
                        {column.cards.length}개 카드 접힘
                    </p>
                )}
            </section>
        );
    }

    return (
        <div
            ref={boardRef}
            role="region"
            aria-label={label}
            aria-busy={saving || undefined}
            tabIndex={0}
            className={cn("min-w-0 overflow-x-auto", className)}
            {...props}
            data-ui="kanban"
        >
            {lanes.map((lane, laneIndex) => (
                <div key={lane.id ?? "all"} data-kanban-swimlane={
                    lane.id ?? undefined
                } role={lane.title ? "group" : undefined}
                    aria-label={lane.title ?? undefined}
                    className="mb-[var(--space-3)] flex min-w-max gap-[var(--space-3)] pb-2">
                    {lane.title && <h3 className={"sticky left-0 z-10 m-0 " +
                        "w-28 shrink-0 self-start rounded-sm bg-surface " +
                        "px-2 py-3 text-sm font-semibold"}>
                        {lane.title}
                    </h3>}
                    {columns.map((column, columnIndex) =>
                        renderColumn(column, columnIndex, lane, laneIndex))}
                </div>
            ))}
            {message && <p role="status" className="sr-only">{message}</p>}
            {error && <div className="mt-2 flex flex-wrap items-center gap-2">
                <p role="alert" className="m-0 text-sm text-danger">{error}</p>
                {failedMove && <button ref={retryRef} type="button"
                    disabled={saving}
                    onClick={() => void retryMove()}
                    className={"rounded-sm border border-border px-2 py-1 " +
                        "text-xs focus-visible:outline-2 " +
                        "focus-visible:outline-focus disabled:opacity-50"}>
                    재시도
                </button>}
            </div>}
            <span className="sr-only" role="status" aria-live="polite">
                {announcement}
            </span>
        </div>
    );
}

export { Kanban, moveKanbanCard };
export type {
    KanbanCard, KanbanColumn, KanbanMove, KanbanProps, KanbanSwimlane,
};
